Object.assign(window.I18N,{"Wer hat dich am meisten angegriffen?": "Who attacked you the most?", "niemand besonders": "nobody in particular", "konnte von einem Angriff auf {0} nicht ablassen, obwohl er dort deutlich mehr verlor als gewann": "couldn’t let go of an attack on {0}, although it lost far more there than it gained", "Sunk-Cost-Effekt": "sunk cost fallacy", "Verlustaversion": "loss aversion", "Vergeltungsimpuls": "retaliation impulse", "Impulsives Schnelldenken": "impulsive fast thinking", "Feindseligkeitsverzerrung": "hostile attribution bias", "Introspektionsillusion": "introspection illusion", "Selbstwertdienliche Verzerrung": "self-serving bias", "Kognitive Verzerrung – Erklärung öffnen": "Cognitive bias – open explanation", "Psychologie": "Psychology"});
