Object.assign(window.I18N,{"Bestenliste": "Leaderboard", "Tipp: Mit einem Spielernamen (👤) zählen deine Online-Partien für die Bestenliste.": "Tip: with a player name (👤) your online games count for the leaderboard.", "🏆 Bestenliste: {0} Punkte ({1})": "🏆 Leaderboard: {0} points ({1})", "🏆 Ergebnis gemeldet – es zählt, sobald ein Mitspieler mit Spielernamen es bestätigt.": "🏆 Result reported – it counts as soon as another player with a player name confirms it.", "🏆 Sieg gegen den Computer in die Rekordliste eingetragen.": "🏆 Win against the computer added to the records."});
